let state='start',mode='journey',travel='walk',elapsed=0,day=1,phase=0,score=0,hp=100,coreHp=150,level=1,kills=0,dawn=0,dusk=0,spawnTimer=0,fireTimer=0,pulseCD=0,invuln=0,boss=null,bossDone=false,phaseIndex=-1,yaw=0,pitch=.12,muted=false,audio,noticeTime=0,best=0;
