function spawn(isBoss=false){const a=Math.random()*Math.PI*2;const p=isBoss?player.position:phase===2?core.position:player.position;const m=new THREE.Mesh(enemyGeo,mat(isBoss?'#9d697f':'#b17789'));m.position.set(THREE.MathUtils.clamp(p.x+Math.sin(a)*28,-210,210),Math.max(height(p.x,p.z)+5,p.y+8),THREE.MathUtils.clamp(p.z+Math.cos(a)*28,-210,210));scene.add(m);if(isBoss){m.scale.set(5,5,5);const ring=mesh(new THREE.TorusGeometry(1.5,.12,5,24),palette.cream,m);ring.rotation.x=Math.PI/2;}const e={m,hp:isBoss?230+day*70:22+day*5,max:isBoss?230+day*70:22+day*5,boss:isBoss,dead:false,cool:2,wind:0};enemies.push(e);if(isBoss){boss=e;say('蚀日巨灵现身：亮环蓄力后发射追击弹，保持移动！');}}
